import React, { useState } from "react";
import axios from "axios";

// This is the URL of your Spring Boot backend endpoint.
// Make sure the backend is running on port 8080 before testing this.
const REGISTER_API_URL = "http://localhost:8080/api/users/register";

export default function Register() {
  // One state object holding all 4 form fields
  const [form, setForm] = useState({
    fullName: "",
    email: "",
    phone: "",
    password: "",
  });

  const [message, setMessage] = useState(""); // success message
  const [error, setError] = useState("");     // error message
  const [loading, setLoading] = useState(false);

  // Updates the matching field in `form` whenever the user types
  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault(); // stop the browser from reloading the page
    setError("");
    setMessage("");
    setLoading(true);

    try {
      // This sends a POST request with `form` as the JSON body
      const response = await axios.post(REGISTER_API_URL, form);

      // response.data looks like: { success: true, message: "...", data: { id, fullName, ... } }
      setMessage(response.data.message);

      // Clear the form after successful registration
      setForm({ fullName: "", email: "", phone: "", password: "" });
    } catch (err) {
      // If backend sent { success: false, message: "Email already registered" }
      if (err.response && err.response.data && err.response.data.message) {
        setError(err.response.data.message);
      } else {
        setError("Could not reach the server. Is the backend running on port 8080?");
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={styles.wrapper}>
      <form style={styles.card} onSubmit={handleSubmit}>
        <h2>Create your account</h2>

        {error && <div style={styles.error}>{error}</div>}
        {message && <div style={styles.success}>{message}</div>}

        <label style={styles.label}>Full Name</label>
        <input
          style={styles.input}
          name="fullName"
          placeholder="e.g. Om Sharma"
          value={form.fullName}
          onChange={handleChange}
          required
        />

        <label style={styles.label}>Email</label>
        <input
          style={styles.input}
          type="email"
          name="email"
          placeholder="e.g. om@example.com"
          value={form.email}
          onChange={handleChange}
          required
        />

        <label style={styles.label}>Phone Number</label>
        <input
          style={styles.input}
          name="phone"
          placeholder="10-digit mobile number"
          value={form.phone}
          onChange={handleChange}
          required
        />

        <label style={styles.label}>Password</label>
        <input
          style={styles.input}
          type="password"
          name="password"
          placeholder="At least 6 characters"
          value={form.password}
          onChange={handleChange}
          required
        />

        <button style={styles.button} type="submit" disabled={loading}>
          {loading ? "Registering..." : "Register"}
        </button>
      </form>
    </div>
  );
}

const styles = {
  wrapper: {
    display: "flex",
    justifyContent: "center",
    paddingTop: "60px",
  },
  card: {
    background: "#fff",
    padding: "32px",
    borderRadius: "12px",
    boxShadow: "0 4px 16px rgba(0,0,0,0.08)",
    width: "100%",
    maxWidth: "380px",
    display: "flex",
    flexDirection: "column",
    gap: "6px",
  },
  label: { fontSize: "13px", color: "#555", marginTop: "8px" },
  input: {
    padding: "10px",
    borderRadius: "6px",
    border: "1px solid #ccc",
    fontSize: "15px",
  },
  button: {
    padding: "12px",
    borderRadius: "6px",
    border: "none",
    background: "#1b1f3b",
    color: "#fff",
    fontWeight: "bold",
    cursor: "pointer",
    marginTop: "16px",
  },
  error: {
    background: "#ffe5e5",
    color: "#c0392b",
    padding: "10px",
    borderRadius: "6px",
    fontSize: "14px",
  },
  success: {
    background: "#e5ffe9",
    color: "#1a7a34",
    padding: "10px",
    borderRadius: "6px",
    fontSize: "14px",
  },
};
